mapper.select:
SELECT *
FROM learning_wordbook_entry
WHERE wordbook_id = #{wordbookId}
  AND normalized_term = #{normalizedTerm}
LIMIT 1

mapper.update:
UPDATE learning_wordbook_entry
SET progress_id = CASE id
    WHEN #{item.id} THEN #{item.progressId}
    END,
    catalog_entry_id = CASE id
    WHEN #{item.id} THEN #{item.catalogEntryId}
    END,
    snapshot_parsed_json = CASE id
    WHEN #{item.id} THEN #{item.snapshotParsedJson}
    END,
    snapshot_time = CASE id
    WHEN #{item.id} THEN #{item.snapshotTime}
    END,
    card_status = CASE id
    WHEN #{item.id} THEN #{item.cardStatus}
    END,
    deleted = 0,
    update_time = #{list[0].updateTime},
    update_by = #{list[0].updateBy}
WHERE id IN
#{item.id}
